```jsx
// Функциональный компонент с хуками
function UserProfile({ userId }) {
  const [user, setUser] = useState(null);

  // mount + update при изменении userId (componentDidMount + componentDidUpdate)
  useEffect(() => {
    let cancelled = false;
    fetchUser(userId).then(u => {
      if (!cancelled) setUser(u);
    });
    return () => { cancelled = true; };  // cleanup (componentWillUnmount)
  }, [userId]);  // deps: при изменении userId

  // mount only (componentDidMount)
  useEffect(() => {
    const timer = setInterval(() => console.log('tick'), 1000);
    return () => clearInterval(timer);  // cleanup (componentWillUnmount)
  }, []);

  if (!user) return <Loading />;
  return <div>{user.name}</div>;
}

// Классовый компонент (легаси)
class UserProfile extends React.Component {
  constructor(props) {
    super(props);
    this.state = { user: null };
  }
  componentDidMount() {
    fetchUser(this.props.userId).then(u => this.setState({user: u}));
  }
  componentDidUpdate(prevProps) {
    if (prevProps.userId !== this.props.userId) {
      fetchUser(this.props.userId).then(u => this.setState({user: u}));
    }
  }
  componentWillUnmount() {
    // очистка
  }
  render() {
    return this.state.user ? <div>{this.state.user.name}</div> : <Loading />;
  }
}
```

