const { count, name } = state;  // НЕ реактивно
// Решение: toRefs
const { count: c, name: n } = toRefs(state);  // c, n — ref, реактивны

// Переназначение
count.value = 5;  // ref — можно
// state = reactive({...});  // reactive — нельзя (теряет реактивность)
Object.assign(state, {count: 5, name: 'Bob'});  // правильно

// Передача в функцию
function increment(c) { c.value++; }  // ref — работает
increment(count);
// reactive при деструктуризации в функции теряет реактивность
