});

// watchEffect — сразу запускается, автоотслеживание
watchEffect(() => {
  console.log('count is', state.count);  // отслеживает state.count
});

// Деструктуризация с toRefs
const { count: c, user: u } = toRefs(state);  // c, u — ref, реактивны

// shallowReactive — только верхний уровень
const shallow = shallowReactive({ a: { b: 1 } });
shallow.a = { b: 2 };  // реактивно (верхний уровень)
shallow.a.b = 3;  // НЕ реактивно (вложенный)
