```jsx
// Классовый компонент
class UserList extends React.Component {
  constructor(props) {
    super(props);
    this.state = { users: [], loading: true };
  }

  async componentDidMount() {
    // Загрузка данных после mount
    const users = await fetch('/api/users').then(r => r.json());
    this.setState({ users, loading: false });

    // Подписка
    window.addEventListener('resize', this.handleResize);

    // Таймер
    this.interval = setInterval(() => this.tick(), 1000);
  }

  componentWillUnmount() {
    // Очистка (аналог cleanup из useEffect)
    window.removeEventListener('resize', this.handleResize);
    clearInterval(this.interval);
  }

  handleResize = () => { /* ... */ };
  tick = () => { /* ... */ };

  render() {
    if (this.state.loading) return <Loading />;
    return this.state.users.map(u => <div key={u.id}>{u.name}</div>);
  }
}

// Функциональный эквивалент (useEffect)
function UserList() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Аналог componentDidMount
    const fetchUsers = async () => {
      const data = await fetch('/api/users').then(r => r.json());
      setUsers(data);
      setLoading(false);
    };
    fetchUsers();

    // Подписка
    const handleResize = () => { /* ... */ };
    window.addEventListener('resize', handleResize);

    // Таймер
    const interval = setInterval(() => { /* ... */ }, 1000);

    // Cleanup (аналог componentWillUnmount)
    return () => {
      window.removeEventListener('resize', handleResize);
      clearInterval(interval);
    };
  }, []);  // пустой deps — только mount

  if (loading) return <Loading />;
  return users.map(u => <div key={u.id}>{u.name}</div>);
}
